Voici un exemple de code pour un bot Discord à l'aide de Discord.js v14, qui implémente une commande "bannir" :

```javascript
const { Client, GatewayIntentBits, SlashCommandBuilder } = require('discord.js');

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

// Ajoutez votre propre clé de bot Discord ici
client.login('Votre clé de bot Discord');

client.on('ready', () => {
  console.log(`Bot ${client.user.tag} est prêt!`);
});

client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  const { commandName } = interaction;

  if (commandName === 'ban') {
    if (!interaction.memberPermissions.has('BAN_MEMBERS')) {
      return interaction.reply({
        content: 'Vous n'avez pas les permissions nécessaires pour effectuer cette commande.',
        ephemeral: true,
      });
    }

    const member = interaction.options.getUser('user');
    if (!member) {
      return interaction.reply({
        content: 'Veuillez fournir un utilisateur à bannir.',
        ephemeral: true,
      });
    }

    await interaction.guild.members.ban(member, { days: 7, reason: `Bannissement effectué par ${interaction.user.tag}` });

    return interaction.reply({
      content: `${member.user.tag} a été banni avec succès.`,
      ephemeral: false,
    });
  }
});

const data = new SlashCommandBuilder()
  .setName('ban')
  .setDescription('Bannit un utilisateur.')
  .addUserOption(option =>
    option
      .setName('user')
      .setDescription('L'utilisateur à bannir')
      .setRequired(true),
  );

client.on('ready', () => {
  client.application.commands.create({
    application_id: client.user.id,
    guild_id: 'Votre ID de serveur Discord',
    name: data.name,
    description: data.description,
    options: data.toJSON(),
  });
});
```

Remplacez les variables suivantes avec vos propres valeurs :

- `Votre clé de bot Discord` : la clé de bot Discord que vous avez générée sur le site web de développement de Discord.
- `Votre ID de serveur Discord` : l'ID de votre serveur Discord.

Ensuite, vous pouvez utiliser la commande `/ban` dans votre serveur Discord en sélectionnant le bot Discord, en tapant `/ban`, en sélectionnant l'utilisateur que vous souhaitez bannir, puis en confirmant la commande. Notez que vous devez également avoir les permissions de bannir des utilisateurs sur votre serveur Discord.

Voici un cadre de test de haute qualité dans Cypress, qui utilise Docker et utilise également la capacité de Cypress à capturer des captures d'écran et à les enregistrer :

```javascript
// cypress/support/index.js

/**
 * Importez les bibliothèques de Docker et d'ImageMagick.
 * Ces bibliothèques sont utilisées pour capturer des captures d'écran et les enregistrer.
 */
const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

// Définissez les chemins absolus vers les répertoires de Docker et d'ImageMagick.
const dockerPath = '/usr/bin/docker';
const magickPath = '/usr/bin/convert';

// Définissez les chemins vers les captures d'écran.
const screenshotPath = './screenshots';
const failedScreenshotPath = './failed-screenshots';

// Créez les répertoires s'ils n'existent pas.
if (!fs.existsSync(screenshotPath)) {
  fs.mkdirSync(screenshotPath);
}

if (!fs.existsSync(failedScreenshotPath)) {
  fs.mkdirSync(failedScreenshotPath);
}

/**
 * Fonction de capture de capture d'écran.
 *
 * @param {string} testName - Nom du test actuel.
 * @param {string} filePath - Chemin de sauvegarde de la capture d'écran.
 * @param {boolean} isFailed - Indique si la capture d'écran a échoué.
 */
function captureScreenshot(testName, filePath, isFailed) {
  // Exécutez Docker pour obtenir l'image de l'environnement de test actuel.
  const imageId = execSync(`${dockerPath} images --format='{{.ID}}' --filter='reference={{.}}' ${process.env.CYPRESS_BASE_IMAGE}`).toString().trim();

  // Exécutez ImageMagick pour convertir l'image en PNG.
  const command = `${magickPath} -format png -depth 8 "${imageId}:/app/screenshots/${testName}.png" "${filePath}"`;
  execSync(command);

  // Supprimez l'image générée temporairement.
  execSync(`docker image prune -f ${imageId}`);
}

/**
 * Fonction de gestion des erreurs de capture d'écran.
 *
 * @param {string} testName - Nom du test actuel.
 * @param {Error} error - Erreur de capture d'écran.
 */
function handleScreenshotError(testName, error) {
  console.error(`Erreur de capture d'écran pour "${testName}": ${error.message}`);

  // Enregistrez la capture d'écran échouée.
  captureScreenshot(testName, path.join(failedScreenshotPath, `${testName}.png`), true);
}

/**
 * Fonction de configuration de Cypress.
 *
 * @param {Cypress} Cypress - Instance Cypress.
 */
export function configureCypress(Cypress) {
  Cypress.on('task', {
    captureScreenshot(testName, options) {
      const { fullPage, clip } = options;
      const filePath = path.join(
        screenshotPath,
        `${testName}.${fullPage ? 'full' : 'partial'}${clip ? '-clip' : ''}.png`
      );

      try {
        // Capturez la capture d'écran.
        captureScreenshot(testName, filePath, false);

        // Supprimez les captures d'écran temporaires.
        execSync(`find ${screenshotPath} -mtime +1 -delete`);

        return filePath;
      } catch (error) {
        handleScreenshotError(testName, error);
        return null;
      }
    },
  });
}
```

Voici comment utiliser ce cadre de test :

1. Créez un nouveau projet Cypress et téléchargez le module Cypress Docker.

2. Créez un fichier `.env` à la racine de votre projet Cypress et configurez-le comme suit :

   ```
   CYPRESS_BASE_IMAGE=<IMAGE_NAME>:<TAG>
   ```

   Remplacez `<IMAGE_NAME>` et `<TAG>` par votre propre image Docker.

3. Créez un nouveau fichier `index.js` dans le répertoire `cypress/support` et copiez le contenu de la fonction `configureCypress()` ci-dessus.

4. Exécutez les tests Cypress en utilisant la commande suivante :

   ```
   npx cypress run --spec cypress/integration/**/*.spec.js
   ```

   Les captures d'écran seront enregistrées dans le répertoire `screenshots` et les captures d'écran échouées seront enregistrées dans le répertoire `failed-screenshots`.

5. Pour configurer le chemin de sortie des captures d'écran, vous pouvez définir les variables d'environnement suivantes :

   ```
   CYPRESS_SCREENSHOT_FOLDER=<CUSTOM_FOLDER_NAME>
   CYPRESS_FAILED_SCREENSHOT_FOLDER=<CUSTOM_FOLDER_NAME>
   ```

   Remplacez `<CUSTOM_FOLDER_NAME>` par votre propre chemin de sortie de capture d'écran.

Cela devrait vous fournir une configuration de capture de capture d'écran de haute qualité dans Cypress, utilisant Docker et enregistrant les captures d'écran capturées. Remarquez que vous devez également configurer votre propre image Docker pour exécuter les tests Cypress dans un conteneur Docker. Pour plus d'informations, consultez la documentation Cypress Docker.

Voici une fonction C++ qui prend une référence à un std::string contenant du texte au format Markdown et renvoie un std::string contenant du texte au format HTML en utilisant la bibliothèque Pug (jusqu'à la version 2.0.0-beta.11) :

```cpp
#include <iostream>
#include <string>
#include <pugixml.hpp>

// Fonction pour convertir du Markdown en HTML
std::string markdownToHtml(const std::string& markdown) {
    // Créer une instance de Pug pour compiler le template
    pugi::xml_document doc;
    pugi::xml_node html_node = doc.append_child("html");
    html_node.append_child(pugi::node_pcdata).set_value(markdown.c_str());

    // Charger le template HTML
    pugi::xml_parse_result result = doc.load_file("template.html");

    if (!result) {
        std::cerr << "Erreur lors de l'analyse du template HTML: "
            << result.description() << std::endl;
        return {};
    }

    // Compiler le template avec le contenu Markdown
    std::string html;
    std::stringstream ss;
    doc.save(ss);
    ss.seekg(0, std::ios::end);
    html.resize(ss.tellg());
    ss.seekg(0, std::ios::beg).read(&html[0]);

    return html;
}

int main() {
    std::string markdown = "Voici un **exemple** de *texte* en **Markdown**! ";

    std::string html = markdownToHtml(markdown);

    std::cout << "Texte Markdown:\n" << markdown << "\n\n";
    std::cout << "Texte HTML:\n" << html << std::endl;

    return 0;
}
```

Pour utiliser cette fonction, vous devez d'abord télécharger et compiler Pug (https://pugjs.org/api/getting-started.html). Une fois que cela est fait, créez un fichier nommé `template.html` dans le même répertoire que votre programme C++ contenant le template HTML suivant :

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Markdown to HTML</title>
</head>
<body>
    <!-- Ajouter le contenu Markdown ici -->
    {{#this}}
</body>
</html>
```

